pub fn bytes_are(out: impl AsRef<[u8]>, n: usize, lit: &'static str) -> bool {
    let out: &[u8] = out.as_ref();
    if (n != lit.len()) {
        return false;
    }
    let mut k: usize = 0;
    while (k < n) {
        if (out[(k) as usize] != lit.as_bytes()[(k) as usize]) {
            return false;
        }
        k = (k + 1);
    }
    return true;
}

