pub fn put_str(dst: &mut [u8], cap: usize, w: usize, s: &'static str, s_len: usize) -> usize {
    let mut i: usize = 0;
    while (i < s_len) {
        if ((w + i) < cap) {
            dst[((w + i)) as usize] = s.as_bytes()[(i) as usize];
        }
        i += 1;
    }
    return (w + s_len);
}

pub const V_BEHIND: u8 = 2;

pub const V_BLOCKED: u8 = 3;

pub const V_NOT_RUN: u8 = 4;

pub const V_RED: u8 = 5;

pub const V_VACUOUS: u8 = 1;

pub const V_VERIFIED: u8 = 0;

pub fn line_end(text: &'static str, at: usize) -> usize {
    let mut k: usize = at;
    while ((k < text.len()) && (text.as_bytes()[(k) as usize] != 10)) {
        k = (k + 1);
    }
    return k;
}

pub fn name(v: u8) -> &'static str {
    if (v == V_VERIFIED) {
        return "verified";
    }
    if (v == V_VACUOUS) {
        return "vacuous";
    }
    if (v == V_BEHIND) {
        return "behind";
    }
    if (v == V_BLOCKED) {
        return "blocked";
    }
    if (v == V_NOT_RUN) {
        return "not-run";
    }
    if (v == V_RED) {
        return "RED";
    }
    return "UNREAD";
}

pub fn span_is(text: &'static str, from: usize, to: usize, lit: &'static str) -> bool {
    if ((to < from) || ((to - from) != lit.len())) {
        return false;
    }
    let mut k: usize = 0;
    while (k < lit.len()) {
        if (text.as_bytes()[((from + k)) as usize] != lit.as_bytes()[(k) as usize]) {
            return false;
        }
        k = (k + 1);
    }
    return true;
}

pub fn why(v: u8) -> &'static str {
    if (v == V_VERIFIED) {
        return "verified: t27b passes with runtime asserts";
    }
    if (v == V_VACUOUS) {
        return "vacuous: it passes with 0 runtime asserts";
    }
    if (v == V_BEHIND) {
        return "behind: the reference passes, t27b is blocked";
    }
    if (v == V_BLOCKED) {
        return "blocked: neither the reference nor t27b runs it";
    }
    if (v == V_NOT_RUN) {
        return "not run: the lab ran only the reference";
    }
    if (v == V_RED) {
        return "RED: a failure, timeout, crash or mismatch";
    }
    return "UNREAD: the lab's result for it cannot be read";
}

